from pathlib import Path
import json,statistics as st
D=Path(__file__).resolve().parent
R=json.loads((D/'results.json').read_text());dr=json.loads((D/'weight-drift.json').read_text()); H=R['histories']; assert len(H)==len(dr)==6
rise=[];body=[];lat=[];pre=[];probes={e:[] for e in ('rake','umbrella')};settles=[];needs=[];behavior=[]; curves=[]
for seed in range(3):
 f,p=H[2*seed:2*seed+2]; assert f['eta']==0 and p['eta']==.01 and f['seed']==p['seed']==seed
 for n in ('kindness_slow','slow_trust_build'):
  fv,pv=[v['battery'][n] for v in (f,p)];diff=[y['trust']-x['trust'] for x,y in zip(fv,pv)];curves.append(diff);rise.append(diff[3]-diff[0]);body.append(max(abs(y['body']-x['body']) for x,y in zip(fv,pv)))
 times=[]
 for v in (f,p):
  arc=v['battery']['apology_repair'];k=next(i for i,t in enumerate(arc) if t['sit']=='sorry');assert k==3;pre.append(arc[k-1]['fear']);times.append(next((j for j,t in enumerate(arc[k:],1) if t['fear']<.10),6))
 lat.append(times)
 for e in probes:
  for v in (f,p):
   t=v['probes'][e][0];assert t['event']==e;probes[e].append((t['intent'],t['fear']))
 for x,y in zip(f['probes']['sleep'],p['probes']['sleep']):settles.append((x['intent']=='settle',y['intent']=='settle'))
 x,y=[v['probes']['quiet'][0] for v in (f,p)];assert x['event']==y['event']==None;needs.append([abs(x[k]-y[k]) for k in ('hunger','sleep')]);pairs=[(x,y) for n in f['battery'] for x,y in zip(f['battery'][n],p['battery'][n])];assert len(pairs)==192;behavior.append(dict(intent=sum(x['intent']!=y['intent'] for x,y in pairs),tag=sum((x['mood'],x['level'])!=(y['mood'],y['level']) for x,y in pairs),cx_move_max=max(abs(x['cx']['move']-y['cx']['move']) for x,y in pairs)))
a=st.mean(rise);b=st.mean(y-x for x,y in lat);ap=lambda t:t[0] in ('to_you','beg');gen={e:st.mean(int(ap(y))-int(ap(x)) for x,y in zip(v[::2],v[1::2])) for e,v in probes.items()};mx=list(map(max,zip(*needs)));settle=sum(x for x,y in settles);p4=settle>0 and all(x==y for x,y in settles) and max(mx)<=.01
verdict=[.001<=a<=.05,b<=-1,max(gen.values())<=.05,p4]; S=dict(supported=verdict,P1_delta=a,early_deltas=rise,trust_difference_curves=curves,P2_latency_frozen_plastic=lat,pre_apology_fear=pre,P3=probes,P3_approach_delta=gen,P4_baseline_max=mx,P4_settles=settles,battery_behavior=behavior);(D/'scores.json').write_text(json.dumps(S,indent=2));lab=lambda i:'supported' if verdict[i] else 'not supported';d=dr[1::2];assert all(not x['changed'] for x in dr[::2]);lines=['Duck plasticity — offline paired stimulus-window assay',f'24 conversations × 8 turns × 3 paired seeds per arm; prereg SHA256 {R["prereg"]}.',f'P1 {lab(0)}: extra early rise in blended trust {a:+.6f} (predicted +0.001 to +0.05). Maximum paired body-trust difference on these arcs: {max(body):.6g}.',f'P2 {lab(1)}: first turn below fear 0.10, frozen/plastic by seed: {lat}; mean shift {b:+.2f} turns. Pre-apology fear range {min(pre):.4f}–{max(pre):.4f}.',f'P3 {lab(2)}: post-kindness approach-rate differences {gen}.']
for e,v in probes.items():lines.append(f'  {e}: intents {sorted(set(x for x,y in v))}; fear range {min(y for x,y in v):.4f}–{max(y for x,y in v):.4f}. Threat intents come from routing, not learned recognition.')
lines.extend([f'P4 {lab(3)}: {sum(x!=y for x,y in settles)}/{len(settles)} settle decisions differed ({settle} frozen positives); quiet baseline max absolute hunger/sleep differences {mx}.',f'Drift: {d[0]["candidate"]:,} candidate inputs to 331 DAN cells, {d[0]["graph_edges"]:,} total graph entries.',f'Changed entries by seed: {[x["changed"] for x in d]}; at cap: {[x["cap_hits"] for x in d]}.',f'Max relative drift {max(x["max_rel"] for x in d):.3%}; zero sign flips; frozen drift zero. Bounds checked per edge.',f'Battery reply-intent changes by seed: {[x["intent"] for x in behavior]}; mood-tag/level changes: {[x["tag"] for x in behavior]}; max CX move differences: {[x["cx_move_max"] for x in behavior]}.','The gauge directly reads DAN weight deltas; it cannot independently establish behavioral learning.','Scope: only first 200 ms per observation simulated neurally; body clocks retain full scripted gaps. No speech generation, day/night replay, or live traffic.']);changed_tags=[(n,i+1,(x['mood'],x['level']),(y['mood'],y['level'])) for f,p in zip(H[::2],H[1::2]) for n in f['battery'] for i,(x,y) in enumerate(zip(f['battery'][n],p['battery'][n])) if (x['mood'],x['level'])!=(y['mood'],y['level'])];lines.append('Exploratory mood-tag differences (scenario, turn, frozen, plastic): '+str(changed_tags));lines.append('Verdict: synaptic change and a repeatable mood-tag shift, but no acquired choice of action in this battery. No live rollout recommended.');(D/'DUCKPLAST-FINDINGS.md').write_text('\n'.join(lines)+'\n');print('\n'.join(lines))
